<?php
namespace Modules\Inventory\Controllers;
use App\Http\Controllers\ModuleBaseController;
use Illuminate\Http\Request;
use Modules\Inventory\Models\{InventoryAuditLog,InventoryMovement,InventoryTransfer};
class InventoryMovementReportController extends ModuleBaseController { public function index(Request $r){$rows=InventoryMovement::with(['material','user'])->when($r->type,fn($q,$v)=>$q->where('type',$v))->when($r->from,fn($q,$v)=>$q->whereDate('created_at','>=',$v))->when($r->to,fn($q,$v)=>$q->whereDate('created_at','<=',$v))->latest()->paginate(50)->withQueryString();$transfers=InventoryTransfer::with(['asset','fromClassroom','toClassroom'])->latest()->limit(100)->get();return view('inventory::feature',['section'=>'movement-report','title'=>'Báo cáo di chuyển vật tư','rows'=>$rows,'transfers'=>$transfers]);} public function csv(Request $r){$rows=InventoryMovement::with('material')->when($r->type,fn($q,$v)=>$q->where('type',$v))->latest()->get();$callback=function()use($rows){$out=fopen('php://output','w');fputcsv($out,['No','Time','Code','Name','Type','Quantity','Reference','Note']);foreach($rows as $i=>$row)fputcsv($out,[$i+1,$row->created_at?->format('Y-m-d H:i'),$row->material?->code,$row->material?->name,$row->type,$row->quantity,$row->reference,$row->note]);fclose($out);};return response()->streamDownload($callback,'inventory-movements.csv',['Content-Type'=>'text/csv; charset=UTF-8']);} }
